import { PhoneInput } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof PhoneInput>, 'label' | 'value' | 'country'> = {
    label: 'Phone',
    value: '(31) 9 8123-4567',
    country: 'BR',
  };
  const [country, setCountry] = useState(args.country);
  const [value, setValue] = useState(String(args.value));
  return (
    <PhoneInput
      {...args}
      country={country}
      value={value}
      onCountryChange={(next) => setCountry(next.code)}
      onChange={(event) => setValue(event.target.value)}
    />
  );
}

import { phoneCountries } from '@refy-design/web';
import { PhoneInput } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof PhoneInput>,
    'label' | 'value' | 'country' | 'hint'
  > = {
    label: 'Phone',
    value: '(31) 9 8123-4567',
    country: 'BR',
    hint: phoneCountries.map((item) => `${item.flag} ${item.callingCode}`).join(' · '),
  };
  return <PhoneInput {...args} />;
}

